@namespace sv_c2f39a08d1864e7d983303b90d1bc064.Components.Pages.Settings

<nav class="settings-sidebar">
    <h5 class="px-3 py-2 text-muted text-uppercase fw-bold" style="font-size: 0.75rem; letter-spacing: 0.05em;">Settings</h5>
    <ul class="nav flex-column">
        @foreach (var section in Sections)
        {
            <li class="nav-item">
                <button class="nav-link settings-nav-link @(ActiveSection == section.Key ? "active" : "")"
                        @onclick="() => OnSectionChanged.InvokeAsync(section.Key)">
                    <span class="me-2">@section.Icon</span>
                    @section.Label
                </button>
            </li>
        }
    </ul>
</nav>

@code {
    [Parameter] public string ActiveSection { get; set; } = "profile";
    [Parameter] public EventCallback<string> OnSectionChanged { get; set; }

    private record SectionInfo(string Key, string Label, string Icon);

    private static readonly SectionInfo[] Sections =
    [
        new("profile", "Profile", "👤"),
        new("notifications", "Notifications", "🔔"),
        new("security", "Security", "🔒"),
        new("appearance", "Appearance", "🎨")
    ];
}

@namespace sv_c2f39a08d1864e7d983303b90d1bc064.Components.Pages.Settings

<div class="settings-section">
    <h4 class="mb-4">Profile</h4>

    <div class="row">
        <div class="col-md-8">
            <div class="mb-3">
                <label class="form-label fw-semibold">Display Name</label>
                <input type="text" class="form-control" @bind="DisplayName" />
            </div>

            <div class="mb-3">
                <label class="form-label fw-semibold">Email</label>
                <input type="email" class="form-control" @bind="Email" />
            </div>

            <div class="mb-3">
                <label class="form-label fw-semibold">Bio</label>
                <textarea class="form-control" rows="4" @bind="Bio"></textarea>
            </div>
        </div>

        <div class="col-md-4 text-center">
            <div class="mb-2">
                <div class="avatar-preview mx-auto">
                    @if (!string.IsNullOrWhiteSpace(AvatarUrl))
                    {
                        <img src="@AvatarUrl" alt="Avatar" class="rounded-circle" style="width: 120px; height: 120px; object-fit: cover;" />
                    }
                    else
                    {
                        <div class="rounded-circle bg-secondary d-flex align-items-center justify-content-center"
                             style="width: 120px; height: 120px;">
                            <span class="text-white fs-1">👤</span>
                        </div>
                    }
                </div>
            </div>
            <div class="mb-3">
                <label class="form-label fw-semibold">Avatar URL</label>
                <input type="url" class="form-control form-control-sm" @bind="AvatarUrl" />
            </div>
        </div>
    </div>

    <div class="d-flex gap-2">
        <button class="btn btn-primary" @onclick="HandleSave" disabled="@IsSaving">
            @if (IsSaving)
            {
                <span class="spinner-border spinner-border-sm me-1"></span>
            }
            Save Changes
        </button>
        <button class="btn btn-outline-secondary" @onclick="HandleDiscard">Discard Changes</button>
    </div>

    @if (ShowSuccess)
    {
        <div class="alert alert-success mt-3 d-flex align-items-center" role="alert">
            <span class="me-2">✅</span> Profile saved successfully!
        </div>
    }
</div>

@code {
    [Parameter] public Models.UserProfile? Profile { get; set; }
    [Parameter] public EventCallback<Models.UserProfile> OnSave { get; set; }

    private string DisplayName = "";
    private string Email = "";
    private string AvatarUrl = "";
    private string Bio = "";
    private bool IsSaving;
    private bool ShowSuccess;

    protected override void OnParametersSet()
    {
        if (Profile is not null && !_initialized)
        {
            LoadFromProfile(Profile);
            _initialized = true;
        }
    }

    private bool _initialized;

    private void LoadFromProfile(Models.UserProfile profile)
    {
        DisplayName = profile.DisplayName;
        Email = profile.Email;
        AvatarUrl = profile.AvatarUrl;
        Bio = profile.Bio;
    }

    private async Task HandleSave()
    {
        IsSaving = true;
        ShowSuccess = false;
        var updated = new Models.UserProfile(DisplayName, Email, AvatarUrl, Bio);
        await OnSave.InvokeAsync(updated);
        IsSaving = false;
        ShowSuccess = true;
        _ = HideSuccessAfterDelay();
    }

    private async Task HideSuccessAfterDelay()
    {
        await Task.Delay(3000);
        ShowSuccess = false;
        await InvokeAsync(StateHasChanged);
    }

    private void HandleDiscard()
    {
        if (Profile is not null)
        {
            LoadFromProfile(Profile);
        }
        ShowSuccess = false;
    }
}

@namespace sv_c2f39a08d1864e7d983303b90d1bc064.Components.Pages.Settings

<div class="settings-section">
    <h4 class="mb-4">Notifications</h4>

    <div class="mb-4">
        <h6 class="text-muted mb-3">Notification Channels</h6>

        <div class="form-check form-switch mb-3">
            <input class="form-check-input" type="checkbox" id="emailNotif" @bind="EmailNotifications" />
            <label class="form-check-label" for="emailNotif">
                <span class="fw-semibold">Email Notifications</span>
                <br /><small class="text-muted">Receive notifications via email</small>
            </label>
        </div>

        <div class="form-check form-switch mb-3">
            <input class="form-check-input" type="checkbox" id="pushNotif" @bind="PushNotifications" />
            <label class="form-check-label" for="pushNotif">
                <span class="fw-semibold">Push Notifications</span>
                <br /><small class="text-muted">Receive push notifications in your browser</small>
            </label>
        </div>

        <div class="form-check form-switch mb-3">
            <input class="form-check-input" type="checkbox" id="weeklyDigest" @bind="WeeklyDigest" />
            <label class="form-check-label" for="weeklyDigest">
                <span class="fw-semibold">Weekly Digest</span>
                <br /><small class="text-muted">Receive a weekly summary of activity</small>
            </label>
        </div>
    </div>

    <div class="mb-4">
        <h6 class="text-muted mb-3">Muted Channels</h6>
        <p class="small text-muted">Check channels you want to mute:</p>

        @foreach (var channel in AllChannels)
        {
            var channelId = $"ch-{channel.Replace("#", "").Replace(" ", "")}";
            <div class="form-check mb-2">
                <input class="form-check-input" type="checkbox" id="@channelId"
                       checked="@MutedChannels.Contains(channel)"
                       @onchange="e => ToggleMute(channel, (bool)(e.Value ?? false))" />
                <label class="form-check-label" for="@channelId">@channel</label>
            </div>
        }
    </div>

    <button class="btn btn-primary" @onclick="HandleSave" disabled="@IsSaving">
        @if (IsSaving)
        {
            <span class="spinner-border spinner-border-sm me-1"></span>
        }
        Save Preferences
    </button>

    @if (ShowSuccess)
    {
        <div class="alert alert-success mt-3 d-flex align-items-center" role="alert">
            <span class="me-2">✅</span> Notification preferences saved!
        </div>
    }
</div>

@code {
    [Parameter] public Models.NotificationPrefs? Prefs { get; set; }
    [Parameter] public List<string> AllChannels { get; set; } = [];
    [Parameter] public EventCallback<Models.NotificationPrefs> OnSave { get; set; }

    private bool EmailNotifications;
    private bool PushNotifications;
    private bool WeeklyDigest;
    private List<string> MutedChannels = [];
    private bool IsSaving;
    private bool ShowSuccess;
    private bool _initialized;

    protected override void OnParametersSet()
    {
        if (Prefs is not null && !_initialized)
        {
            EmailNotifications = Prefs.EmailNotifications;
            PushNotifications = Prefs.PushNotifications;
            WeeklyDigest = Prefs.WeeklyDigest;
            MutedChannels = new List<string>(Prefs.MutedChannels);
            _initialized = true;
        }
    }

    private void ToggleMute(string channel, bool isMuted)
    {
        if (isMuted && !MutedChannels.Contains(channel))
            MutedChannels.Add(channel);
        else if (!isMuted)
            MutedChannels.Remove(channel);
    }

    private async Task HandleSave()
    {
        IsSaving = true;
        ShowSuccess = false;
        var updated = new Models.NotificationPrefs(EmailNotifications, PushNotifications, WeeklyDigest, new List<string>(MutedChannels));
        await OnSave.InvokeAsync(updated);
        IsSaving = false;
        ShowSuccess = true;
        _ = HideSuccessAfterDelay();
    }

    private async Task HideSuccessAfterDelay()
    {
        await Task.Delay(3000);
        ShowSuccess = false;
        await InvokeAsync(StateHasChanged);
    }
}

@namespace sv_c2f39a08d1864e7d983303b90d1bc064.Components.Pages.Settings

<div class="settings-section">
    <h4 class="mb-4">Security</h4>

    <!-- Change Password Panel -->
    <div class="card mb-4">
        <div class="card-header d-flex align-items-center justify-content-between"
             style="cursor: pointer;" @onclick="() => PasswordPanelExpanded = !PasswordPanelExpanded">
            <span class="fw-semibold">🔑 Change Password</span>
            <span>@(PasswordPanelExpanded ? "▲" : "▼")</span>
        </div>
        @if (PasswordPanelExpanded)
        {
            <div class="card-body">
                <div class="mb-3">
                    <label class="form-label">Current Password</label>
                    <input type="password" class="form-control" @bind="CurrentPassword" />
                </div>
                <div class="mb-3">
                    <label class="form-label">New Password</label>
                    <input type="password" class="form-control" @bind="NewPassword" />
                </div>
                <div class="mb-3">
                    <label class="form-label">Confirm New Password</label>
                    <input type="password" class="form-control" @bind="ConfirmPassword" />
                </div>

                @if (!string.IsNullOrEmpty(PasswordError))
                {
                    <div class="alert alert-danger py-2">@PasswordError</div>
                }
                @if (PasswordSuccess)
                {
                    <div class="alert alert-success py-2">✅ Password updated successfully!</div>
                }

                <button class="btn btn-warning" @onclick="HandleChangePassword" disabled="@IsChangingPassword">
                    @if (IsChangingPassword)
                    {
                        <span class="spinner-border spinner-border-sm me-1"></span>
                    }
                    Update Password
                </button>

                @if (Security?.LastPasswordChange is not null)
                {
                    <small class="text-muted ms-3">Last changed: @Security.LastPasswordChange.Value.ToString("MMM dd, yyyy")</small>
                }
            </div>
        }
    </div>

    <!-- Two-Factor Authentication -->
    <div class="card mb-4">
        <div class="card-body d-flex align-items-center justify-content-between">
            <div>
                <h6 class="mb-1">Two-Factor Authentication</h6>
                <span class="badge @(TwoFactorEnabled ? "bg-success" : "bg-secondary")">
                    @(TwoFactorEnabled ? "Enabled" : "Disabled")
                </span>
            </div>
            <div class="form-check form-switch">
                <input class="form-check-input" type="checkbox" @bind="TwoFactorEnabled"
                       style="transform: scale(1.3);" />
            </div>
        </div>
    </div>

    <!-- Active Sessions -->
    <div class="card mb-4">
        <div class="card-header fw-semibold">📱 Active Sessions</div>
        <div class="card-body p-0">
            <div class="table-responsive">
                <table class="table table-hover mb-0">
                    <thead class="table-light">
                        <tr>
                            <th>Device</th>
                            <th>Location</th>
                            <th>Last Active</th>
                            <th></th>
                        </tr>
                    </thead>
                    <tbody>
                        @if (Sessions is not null)
                        {
                            @foreach (var session in Sessions)
                            {
                                <tr>
                                    <td>
                                        @session.Device
                                        @if (session == Sessions.FirstOrDefault())
                                        {
                                            <span class="badge bg-primary ms-1">Current</span>
                                        }
                                    </td>
                                    <td>@session.Location</td>
                                    <td>@FormatLastActive(session.LastActive)</td>
                                    <td>
