@namespace sv_c2f39a08d1864e7d983303b90d1bc064.Components.Pages.Settings

<div class="settings-section">
    <h4 class="mb-4">Profile</h4>

    <div class="row">
        <div class="col-md-8">
            <div class="mb-3">
                <label class="form-label fw-semibold">Display Name</label>
                <input type="text" class="form-control" @bind="DisplayName" />
            </div>

            <div class="mb-3">
                <label class="form-label fw-semibold">Email</label>
                <input type="email" class="form-control" @bind="Email" />
            </div>

            <div class="mb-3">
                <label class="form-label fw-semibold">Bio</label>
                <textarea class="form-control" rows="4" @bind="Bio"></textarea>
            </div>
        </div>

        <div class="col-md-4 text-center">
            <div class="mb-2">
                <div class="avatar-preview mx-auto">
                    @if (!string.IsNullOrWhiteSpace(AvatarUrl))
                    {
                        <img src="@AvatarUrl" alt="Avatar" class="rounded-circle" style="width: 120px; height: 120px; object-fit: cover;" />
                    }
                    else
                    {
                        <div class="rounded-circle bg-secondary d-flex align-items-center justify-content-center"
                             style="width: 120px; height: 120px;">
                            <span class="text-white fs-1">👤</span>
                        </div>
                    }
                </div>
            </div>
            <div class="mb-3">
                <label class="form-label fw-semibold">Avatar URL</label>
                <input type="url" class="form-control form-control-sm" @bind="AvatarUrl" />
            </div>
        </div>
    </div>

    <div class="d-flex gap-2">
