@namespace sv_c2f39a08d1864e7d983303b90d1bc064.Components.Pages.Settings

<div class="settings-section">
    <h4 class="mb-4">Notifications</h4>

    <div class="mb-4">
        <h6 class="text-muted mb-3">Notification Channels</h6>

        <div class="form-check form-switch mb-3">
            <input class="form-check-input" type="checkbox" id="emailNotif" @bind="EmailNotifications" />
            <label class="form-check-label" for="emailNotif">
                <span class="fw-semibold">Email Notifications</span>
                <br /><small class="text-muted">Receive notifications via email</small>
            </label>
        </div>

        <div class="form-check form-switch mb-3">
            <input class="form-check-input" type="checkbox" id="pushNotif" @bind="PushNotifications" />
            <label class="form-check-label" for="pushNotif">
                <span class="fw-semibold">Push Notifications</span>
                <br /><small class="text-muted">Receive push notifications in your browser</small>
            </label>
        </div>

        <div class="form-check form-switch mb-3">
            <input class="form-check-input" type="checkbox" id="weeklyDigest" @bind="WeeklyDigest" />
            <label class="form-check-label" for="weeklyDigest">
                <span class="fw-semibold">Weekly Digest</span>
                <br /><small class="text-muted">Receive a weekly summary of activity</small>
            </label>
        </div>
    </div>

    <div class="mb-4">
        <h6 class="text-muted mb-3">Muted Channels</h6>
        <p class="small text-muted">Check channels you want to mute:</p>

        @foreach (var channel in AllChannels)
        {
            var channelId = $"ch-{channel.Replace("#", "").Replace(" ", "")}";
            <div class="form-check mb-2">
                <input class="form-check-input" type="checkbox" id="@channelId"
                       checked="@MutedChannels.Contains(channel)"
                       @onchange="e => ToggleMute(channel, (bool)(e.Value ?? false))" />
                <label class="form-check-label" for="@channelId">@channel</label>
            </div>
        }
    </div>

    <button class="btn btn-primary" @onclick="HandleSave" disabled="@IsSaving">
        @if (IsSaving)
        {
            <span class="spinner-border spinner-border-sm me-1"></span>
        }
        Save Preferences
    </button>

    @if (ShowSuccess)
    {
        <div class="alert alert-success mt-3 d-flex align-items-center" role="alert">
            <span class="me-2">✅</span> Notification preferences saved!
        </div>
    }
</div>

@code {
    [Parameter] public Models.NotificationPrefs? Prefs { get; set; }
    [Parameter] public List<string> AllChannels { get; set; } = [];
    [Parameter] public EventCallback<Models.NotificationPrefs> OnSave { get; set; }

    private bool EmailNotifications;
    private bool PushNotifications;
    private bool WeeklyDigest;
    private List<string> MutedChannels = [];
    private bool IsSaving;
    private bool ShowSuccess;
    private bool _initialized;

    protected override void OnParametersSet()
    {
        if (Prefs is not null && !_initialized)
        {
            EmailNotifications = Prefs.EmailNotifications;
            PushNotifications = Prefs.PushNotifications;
            WeeklyDigest = Prefs.WeeklyDigest;
            MutedChannels = new List<string>(Prefs.MutedChannels);
            _initialized = true;
        }
    }

    private void ToggleMute(string channel, bool isMuted)
    {
        if (isMuted && !MutedChannels.Contains(channel))
            MutedChannels.Add(channel);
        else if (!isMuted)
            MutedChannels.Remove(channel);
    }

    private async Task HandleSave()
    {
        IsSaving = true;
        ShowSuccess = false;
        var updated = new Models.NotificationPrefs(EmailNotifications, PushNotifications, WeeklyDigest, new List<string>(MutedChannels));
        await OnSave.InvokeAsync(updated);
        IsSaving = false;
        ShowSuccess = true;
        _ = HideSuccessAfterDelay();
    }

    private async Task HideSuccessAfterDelay()
    {
        await Task.Delay(3000);
        ShowSuccess = false;
        await InvokeAsync(StateHasChanged);
    }
}

