+@namespace sv_c2f39a08d1864e7d983303b90d1bc064.Components.Pages.Settings
+
+<div class="settings-section">
+    <h4 class="mb-4">Security</h4>
+
+    <!-- Change Password Panel -->
+    <div class="card mb-4">
+        <div class="card-header d-flex align-items-center justify-content-between"
+             style="cursor: pointer;" @onclick="() => PasswordPanelExpanded = !PasswordPanelExpanded">
+            <span class="fw-semibold">🔑 Change Password</span>
+            <span>@(PasswordPanelExpanded ? "▲" : "▼")</span>
+        </div>
+        @if (PasswordPanelExpanded)
+        {
+            <div class="card-body">
+                <div class="mb-3">
+                    <label class="form-label">Current Password</label>
+                    <input type="password" class="form-control" @bind="CurrentPassword" />
+                </div>
+                <div class="mb-3">
+                    <label class="form-label">New Password</label>
+                    <input type="password" class="form-control" @bind="NewPassword" />
+                </div>
+                <div class="mb-3">
+                    <label class="form-label">Confirm New Password</label>
+                    <input type="password" class="form-control" @bind="ConfirmPassword" />
+                </div>
+
+                @if (!string.IsNullOrEmpty(PasswordError))
+                {
+                    <div class="alert alert-danger py-2">@PasswordError</div>
+                }
+                @if (PasswordSuccess)
+                {
+                    <div class="alert alert-success py-2">✅ Password updated successfully!</div>
+                }
+
+                <button class="btn btn-warning" @onclick="HandleChangePassword" disabled="@IsChangingPassword">
+                    @if (IsChangingPassword)
+                    {
+                        <span class="spinner-border spinner-border-sm me-1"></span>
+                    }
+                    Update Password
+                </button>
+
+                @if (Security?.LastPasswordChange is not null)
+                {
+                    <small class="text-muted ms-3">Last changed: @Security.LastPasswordChange.Value.ToString("MMM dd, yyyy")</small>
+                }
+            </div>
+        }
+    </div>
+
+    <!-- Two-Factor Authentication -->
+    <div class="card mb-4">
+        <div class="card-body d-flex align-items-center justify-content-between">
+            <div>
+                <h6 class="mb-1">Two-Factor Authentication</h6>
+                <span class="badge @(TwoFactorEnabled ? "bg-success" : "bg-secondary")">
+                    @(TwoFactorEnabled ? "Enabled" : "Disabled")
+                </span>
+            </div>
+            <div class="form-check form-switch">
+                <input class="form-check-input" type="checkbox" @bind="TwoFactorEnabled"
+                       style="transform: scale(1.3);" />
+            </div>
+        </div>
+    </div>
+
+    <!-- Active Sessions -->
+    <div class="card mb-4">
+        <div class="card-header fw-semibold">📱 Active Sessions</div>
+        <div class="card-body p-0">
+            <div class="table-responsive">
+                <table class="table table-hover mb-0">
+                    <thead class="table-light">
+                        <tr>
+                            <th>Device</th>
+                            <th>Location</th>
+                            <th>Last Active</th>
+                            <th></th>
+                        </tr>
+                    </thead>
+                    <tbody>
+                        @if (Sessions is not null)
+                        {
+                            @foreach (var session in Sessions)
+                            {
+                                <tr>
+                                    <td>
+                                        @session.Device
+                                        @if (session == Sessions.FirstOrDefault())
+                                        {
+                                            <span class="badge bg-primary ms-1">Current</span>
+                                        }
+                                    </td>
+                                    <td>@session.Location</td>
+                                    <td>@FormatLastActive(session.LastActive)</td>
+                                    <td>
+                                        @if (session != Sessions.FirstOrDefault())
+                                        {
+                                            <button class="btn btn-outline-danger btn-sm"
+                                                    @onclick="() => ShowRevokeDialog(session)">
+                                                Revoke
+                                            </button>
+                                        }
+                                    </td>
+                                </tr>
+                            }
+                        }
+                    </tbody>
+                </table>
+            </div>
+        </div>
+    </div>
+
+    <!-- Revoke Confirmation Dialog -->
+    @if (SessionToRevoke is not null)
+    {
+        <div class="modal-backdrop fade show"></div>
+        <div class="modal fade show d-block" tabindex="-1">
+            <div class="modal-dialog modal-dialog-centered">
+                <div class="modal-content">
+                    <div class="modal-header">
+                        <h5 class="modal-title">Revoke Session</h5>
+                        <button type="button" class="btn-close" @onclick="CancelRevoke"></button>
+                    </div>
+                    <div class="modal-body">
+                        <p>Are you sure you want to revoke this session?</p>
+                        <p class="mb-0">
+                            <strong>Device:</strong> @SessionToRevoke.Device<br />
+                            <strong>Location:</strong> @SessionToRevoke.Location
+                        </p>
+                    </div>
+                    <div class="modal-footer">
+                        <button class="btn btn-secondary" @onclick="CancelRevoke">Cancel</button>
+                        <button class="btn btn-danger" @onclick="ConfirmRevoke" disabled="@IsRevoking">
+                            @if (IsRevoking)
+                            {
+                                <span class="spinner-border spinner-border-sm me-1"></span>
+                            }
+                            Revoke Session
+                        </button>
+                    </div>
+                </div>
+            </div>
+        </div>
+    }
+</div>
+
+@code {
+    [Parameter] public Models.SecuritySettings? Security { get; set; }
+    [Parameter] public EventCallback<(string currentPassword, string newPassword)> OnChangePassword { get; set; }
+    [Parameter] public EventCallback<string> OnRevokeSession { get; set; }
+
+    private bool PasswordPanelExpanded;
+    private string CurrentPassword = "";
+    private string NewPassword = "";
+    private string ConfirmPassword = "";
+    private string? PasswordError;
+    private bool PasswordSuccess;
+    private bool IsChangingPassword;
+
+    private bool TwoFactorEnabled;
+    private List<Models.ActiveSession>? Sessions;
+
+    private Models.ActiveSession? SessionToRevoke;
+    private bool IsRevoking;
+
+    private bool _initialized;
+
+    protected override void OnParametersSet()
+    {
+        if (Security is not null && !_initialized)
+        {
+            TwoFactorEnabled = Security.TwoFactorEnabled;
+            Sessions = new List<Models.ActiveSession>(Security.Sessions);
+            _initialized = true;
+        }
+    }
+
+    private async Task HandleChangePassword()
+    {
+        PasswordError = null;
+        PasswordSuccess = false;
+
+        if (string.IsNullOrWhiteSpace(CurrentPassword))
+        {
+            PasswordError = "Current password is required.";
+            return;
+        }
+        if (string.IsNullOrWhiteSpace(NewPassword) || NewPassword.Length < 8)
+        {
+            PasswordError = "New password must be at least 8 characters.";
+            return;
+        }
+        if (NewPassword != ConfirmPassword)
+        {
+            PasswordError = "New password and confirmation do not match.";
+            return;
+        }
+
+        IsChangingPassword = true;
+        await OnChangePassword.InvokeAsync((CurrentPassword, NewPassword));
+        IsChangingPassword = false;
+        PasswordSuccess = true;
+        CurrentPassword = "";
+        NewPassword = "";
+        ConfirmPassword = "";
+    }
+
+    private void ShowRevokeDialog(Models.ActiveSession session)
+    {
+        SessionToRevoke = session;
+    }
+
+    private void CancelRevoke()
+    {
+        SessionToRevoke = null;
+    }
+
+    private async Task ConfirmRevoke()
+    {
+        if (SessionToRevoke is null) return;
+        IsRevoking = true;
+        await OnRevokeSession.InvokeAsync(SessionToRevoke.Id);
+        Sessions?.Remove(SessionToRevoke);
+        SessionToRevoke = null;
+        IsRevoking = false;
+    }
+
+    private static string FormatLastActive(DateTime lastActive)
+    {
+        var diff = DateTime.UtcNow - lastActive;
+        if (diff.TotalMinutes < 1) return "Just now";
+        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes}m ago";
+        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours}h ago";
+        return $"{(int)diff.TotalDays}d ago";
+    }
+}
