+                </div>
+            }
+        </div>
+
+        <!-- Live Preview -->
+        <div class="col-md-6">
+            <h6 class="fw-semibold mb-2">Preview</h6>
+            <div class="border rounded @PreviewBgClass" style="@PreviewContainerStyle">
+                <div class="@PreviewPaddingClass">
+                    <div class="d-flex align-items-center mb-2" style="@PreviewHeaderStyle">
+                        <span class="me-2">📄</span>
+                        <strong style="@PreviewFontStyle">Sample Page Title</strong>
+                    </div>
+                    <p style="@PreviewFontStyle" class="@PreviewTextClass mb-2">
+                        This is how your content will look with the selected appearance settings.
+                    </p>
+                    <div class="d-flex gap-2 @(CompactMode ? "mb-1" : "mb-2")">
+                        <span class="badge @PreviewBadgeClass">Label</span>
+                        <span class="badge @PreviewBadgeClass">Tag</span>
+                    </div>
+                    <button class="btn btn-sm @PreviewButtonClass" disabled>Sample Button</button>
+                </div>
+            </div>
+        </div>
+    </div>
+</div>
+
+@code {
+    [Parameter] public Models.AppearanceSettings? Settings { get; set; }
+    [Parameter] public EventCallback<Models.AppearanceSettings> OnSave { get; set; }
+
+    private string SelectedTheme = "Light";
+    private string SelectedFontSize = "Medium";
+    private string SelectedLanguage = "English";
+    private bool CompactMode;
+    private bool IsSaving;
+    private bool ShowSuccess;
+    private bool _initialized;
+
+    private static readonly string[] Languages = ["English", "Spanish", "French", "German", "Japanese", "Chinese", "Portuguese"];
+
+    protected override void OnParametersSet()
+    {
+        if (Settings is not null && !_initialized)
+        {
+            SelectedTheme = Settings.Theme;
+            SelectedFontSize = Settings.FontSize;
+            SelectedLanguage = Settings.Language;
+            CompactMode = Settings.CompactMode;
+            _initialized = true;
+        }
+    }
+
+    // Preview computed properties
+    private string PreviewBgClass => SelectedTheme switch
+    {
+        "Dark" => "bg-dark text-light",
+        _ => "bg-white text-dark"
+    };
+
+    private string PreviewContainerStyle => $"min-height: 180px; transition: all 0.3s ease;";
+
+    private string PreviewPaddingClass => CompactMode ? "p-2" : "p-3";
+
+    private string PreviewHeaderStyle => SelectedTheme == "Dark"
+        ? "border-bottom: 1px solid #444; padding-bottom: 8px;"
+        : "border-bottom: 1px solid #dee2e6; padding-bottom: 8px;";
+
+    private string PreviewFontStyle => SelectedFontSize switch
+    {
+        "Small" => "font-size: 0.8rem;",
+        "Large" => "font-size: 1.15rem;",
+        _ => "font-size: 0.95rem;"
+    };
+
+    private string PreviewTextClass => SelectedTheme == "Dark" ? "text-light" : "text-muted";
+
+    private string PreviewBadgeClass => SelectedTheme == "Dark" ? "bg-secondary" : "bg-primary";
+
+    private string PreviewButtonClass => SelectedTheme == "Dark"
+        ? "btn-outline-light"
+        : "btn-outline-primary";
+
+    private async Task HandleSave()
+    {
+        IsSaving = true;
+        ShowSuccess = false;
+        var updated = new Models.AppearanceSettings(SelectedTheme, SelectedFontSize, SelectedLanguage, CompactMode);
+        await OnSave.InvokeAsync(updated);
+        IsSaving = false;
+        ShowSuccess = true;
+        _ = HideSuccessAfterDelay();
+    }
+
+    private async Task HideSuccessAfterDelay()
+    {
+        await Task.Delay(3000);
+        ShowSuccess = false;
+        await InvokeAsync(StateHasChanged);
+    }
+}
