@page "/settings"
@namespace sv_c2f39a08d1864e7d983303b90d1bc064.Components.Pages.Settings
@rendermode InteractiveServer
@using sv_c2f39a08d1864e7d983303b90d1bc064.Models
@using sv_c2f39a08d1864e7d983303b90d1bc064.Services
@inject ISettingsService SettingsService

<PageTitle>Settings</PageTitle>

<div class="settings-dashboard">
    <SettingsSidebar ActiveSection="@activeSection" OnSectionChanged="section => activeSection = section" />

    <div class="settings-content">
        @if (isLoading)
        {
            <div class="d-flex justify-content-center align-items-center" style="min-height: 300px;">
                <div class="spinner-border text-primary" role="status">
                    <span class="visually-hidden">Loading...</span>
                </div>
            </div>
        }
        else
        {
            @switch (activeSection)
            {
                case "profile":
                    <ProfileSection Profile="@profile" OnSave="HandleSaveProfile" />
                    break;
                case "notifications":
                    <NotificationsSection Prefs="@notificationPrefs" AllChannels="@allChannels" OnSave="HandleSaveNotifications" />
                    break;
                case "security":
                    <SecuritySection Security="@securitySettings"
                                     OnChangePassword="HandleChangePassword"
                                     OnRevokeSession="HandleRevokeSession" />
                    break;
                case "appearance":
                    <AppearanceSection Settings="@appearanceSettings" OnSave="HandleSaveAppearance" />
                    break;
            }
        }
    </div>
</div>

@code {
    private string activeSection = "profile";
    private bool isLoading = true;

    private UserProfile? profile;
    private NotificationPrefs? notificationPrefs;
    private SecuritySettings? securitySettings;
    private AppearanceSettings? appearanceSettings;
    private List<string> allChannels = [];

    protected override async Task OnInitializedAsync()
    {
        var profileTask = SettingsService.GetProfileAsync();
        var notifTask = SettingsService.GetNotificationPrefsAsync();
        var securityTask = SettingsService.GetSecuritySettingsAsync();
        var appearanceTask = SettingsService.GetAppearanceAsync();

        await Task.WhenAll(profileTask, notifTask, securityTask, appearanceTask);

        profile = profileTask.Result;
        notificationPrefs = notifTask.Result;
        securitySettings = securityTask.Result;
        appearanceSettings = appearanceTask.Result;

        if (SettingsService is MockSettingsService mock)
        {
            allChannels = mock.GetAllChannels();
        }

        isLoading = false;
    }

    private async Task HandleSaveProfile(UserProfile updated)
    {
        await SettingsService.SaveProfileAsync(updated);
        profile = updated;
    }

    private async Task HandleSaveNotifications(NotificationPrefs updated)
    {
        await SettingsService.SaveNotificationPrefsAsync(updated);
        notificationPrefs = updated;
    }

    private async Task HandleChangePassword((string currentPassword, string newPassword) args)
    {
        await SettingsService.ChangePasswordAsync(args.currentPassword, args.newPassword);
        securitySettings = await SettingsService.GetSecuritySettingsAsync();
    }

    private async Task HandleRevokeSession(string sessionId)
    {
        await SettingsService.RevokeSessionAsync(sessionId);
    }

    private async Task HandleSaveAppearance(AppearanceSettings updated)
    {
        await SettingsService.SaveAppearanceAsync(updated);
        appearanceSettings = updated;
    }
}

